import{_ as h,o as y,a as f,c as i,b as e,F as l,r as d,h as v,E as b,f as _,g as o,e as k,w,t as a,m as L,y as m,n as p,k as x}from"./index-Bk-fjXs2.js";const A={class:"docs-page"},M={class:"docs-inner"},C={class:"sections-grid"},E={class:"section-card__num mono"},S={class:"section-card__title"},T={class:"section-card__desc"},R={key:0,class:"section-card__tags"},D={class:"quick-ref reveal"},O={class:"data-table"},N={class:"mono"},V={class:"mono"},z={__name:"DocsView",setup(F){let r;y(()=>{r=new IntersectionObserver(n=>n.forEach(s=>s.target.classList.toggle("visible",s.isIntersecting)),{threshold:.1}),setTimeout(()=>document.querySelectorAll(".docs-page .reveal").forEach(n=>r.observe(n)),100)}),f(()=>r==null?void 0:r.disconnect());const c=[{id:"overview",num:"01",title:"Project Overview",summary:'When hurricanes and earthquakes knock out the power grid, hospitals and airports rely on backup generators to keep the lights on. We use NASA satellite imagery that captures nighttime lights to detect which critical facilities actually maintained power during 25 major disasters across 17 U.S. states and Turkey (2016–2023). The key insight: areas near facilities with generators stay brighter than their surroundings — we call this the "Resilience Advantage."',tags:["VIIRS VNP46A2","25 Events","Resilience Advantage"]},{id:"data",num:"02",title:"Data Collection & Processing",summary:"No public database of backup generators exists — so we turn to satellite imagery to detect them indirectly. We combine daily nighttime light images from NASA's Black Marble (500m resolution), power outage records from EAGLE-I, and critical facility locations from OpenStreetMap. Each pixel is labeled by its proximity to facilities (buffer zones at 750m/1250m), creating a panel of ~33,700 pixels across 25 events. This section also covers cloud masking, GEE data acquisition, and data quality challenges.",tags:["VNP46A2","EAGLE-I","OSM","Buffer Zones","Cloud QC"]},{id:"eda",num:"03",title:"Exploratory Data Analysis",summary:'Before building models, we need to understand the data. We define the Resilience Ratio (R = NTL/BAU) and discover the "floor effect" — a critical confound where facilities in darker urban cores appear less resilient simply because they start dimmer. We show that different facility types (hospitals vs. fire stations) and city sizes (Miami vs. Lake Charles) produce systematically different resilience signals, with real data visualizations.',tags:["Resilience Ratio","Floor Effect","Facility Groups","City Size"]},{id:"interpretive",num:"04",title:"Interpretive Modeling",summary:"Four statistical models (OLS, MixedLM, Logistic, Cox PH) attack the same hypothesis from different angles — triangulation. Key findings: buffer pixels show +2.8% less NTL decline (MixedLM, p=0.020), 32% lower damage odds (Logit, OR=0.68), and 13% faster recovery (Cox, HR=1.13). But land-use confounding partially explains the effect. LOEO cross-validation reveals severe generalization failure (AUC 0.73→0.45), motivating the predictive modeling phase.",tags:["OLS","MixedLM","Logistic","Cox PH","Triangulation","NLCD Confounding"]},{id:"features",num:"05",title:"Feature Engineering",summary:'We engineer 17 predictive features from the raw data. A key challenge is the "floor effect" — in smaller cities, critical infrastructure is often located in darker areas, which confounds the analysis. We address this with city-level normalization and interaction terms that separate the genuine generator signal from urban brightness patterns.',tags:["17 features","Floor effect","Interactions"]},{id:"models",num:"06",title:"Predictive Models & Probability Maps",summary:"Four model variants (A–D) systematically test what drives prediction: Model A uses all features (AUC 0.967), Model B removes pre-NTL (AUC 0.968), Model C adds building footprints (AUC 0.966), and Model D uses pure NTL behavior only (AUC 0.704). The ensemble model generates per-pixel backup power probability maps for all 25 study areas, validated against Miami-Dade generator permit records.",tags:["RF + XGB","LOEO","4 Model Variants","AUC 0.967"]},{id:"stage3",num:"07",title:"Zip-Code Analysis",summary:"Do areas with more critical facilities experience less severe power outages? This section extends the pixel-level analysis to zip-code-level spatial regression. Four models — OLS, Moran's I, Spatial Error Model, and subgroup analysis — test whether facility density predicts backup power probability across 1,002 zip codes and 22 U.S. disaster events. R² = 0.475, consistent across all city sizes and disaster types.",tags:["1,002 Zip Codes","Spatial Regression","OLS + SEM"]},{id:"conclusions",num:"08",title:"Conclusions & Future Work",summary:"Pure nighttime light behavior achieves AUC 0.704 for generator detection — a real but modest signal. Spatial context raises this to 0.967. The effect is universal across 25 events, 5 disaster types, and 3 city sizes. Commercial generators are detectable; residential are not. This section discusses limitations (resolution, weak labels, gap-filling) and future directions (higher-resolution sensors, utility integration, emission estimation, real-time monitoring).",tags:["Conclusions","Limitations","Future Work"]},{id:"web",num:"09",title:"Dashboard Development",summary:"This interactive dashboard is built with Vue 3 + Vite, featuring MapLibre GL JS for WebGL-accelerated map rendering with per-event probability heatmaps, canvas-rendered facility icons, and satellite/vector basemap switching. The site supports mobile responsive layouts, scroll-triggered animations, and is deployed via GitHub Actions to GitHub Pages.",tags:["Vue 3","Vite","MapLibre GL","GitHub Pages"]},{id:"repro",num:"10",title:"Reproducibility",summary:"All data sources are publicly available (NASA, OpenStreetMap, DOE), and the full analysis pipeline is implemented in Jupyter notebooks. This section provides the exact data product IDs, API endpoints, and key academic references needed to reproduce or extend the analysis.",tags:["GEE","Jupyter","Open data"]}];return(n,s)=>{const g=_("RouterLink");return o(),i("div",A,[e("div",M,[s[3]||(s[3]=e("div",{class:"page-header reveal"},[e("div",{class:"tag tag--cyan",style:{"margin-bottom":"10px"}},"Technical Documentation"),e("h1",{class:"page-header__title"},"Methodology & Data"),e("p",{class:"page-header__desc"},' Overview of the analysis pipeline — from satellite data acquisition to predictive modeling. Click "Read More" on any section for detailed technical documentation. ')],-1)),e("div",C,[(o(),i(l,null,d(c,t=>k(g,{key:t.id,to:`/docs/${t.id}`,class:"section-card reveal",style:p({transitionDelay:`${c.indexOf(t)*.06}s`})},{default:w(()=>[e("div",E,a(t.num),1),e("h3",S,a(t.title),1),e("p",T,a(t.summary),1),t.tags?(o(),i("div",R,[(o(!0),i(l,null,d(t.tags,u=>(o(),i("span",{key:u,class:"tag tag--dim"},a(u),1))),128))])):L("",!0),s[0]||(s[0]=e("div",{class:"section-card__cta"},[m(" Read More "),e("span",{class:"arrow"},"→")],-1))]),_:2},1032,["to","style"])),64))]),e("div",D,[s[2]||(s[2]=e("div",{class:"quick-ref__header"},[e("span",{class:"tag tag--amber"},"Quick Reference"),e("span",{style:{"font-size":"11px",color:"var(--text-muted)"}},"Study Events")],-1)),e("div",O,[e("table",null,[s[1]||(s[1]=e("thead",null,[e("tr",null,[e("th",null,"Event"),e("th",null,"Location"),e("th",null,"Year"),e("th",null,"Type"),e("th",null,"Affected")])],-1)),e("tbody",null,[(o(!0),i(l,null,d(v(b),t=>(o(),i("tr",{key:t.id},[e("td",null,[e("span",{class:"dot",style:p({background:t.color})},null,4),m(a(t.name),1)]),e("td",null,a(t.subtitle),1),e("td",N,a(t.year),1),e("td",null,[e("span",{class:x(["tag",`tag--${t.type}`]),style:{"font-size":"10px"}},a(t.type),3)]),e("td",V,a(t.affectedUsers),1)]))),128))])])])])])])}}},I=h(z,[["__scopeId","data-v-702be1f0"]]);export{I as default};
